import Darwin
import Foundation

/// Shared wire-format pieces for explicitly generated IP transport packets.
/// Generated bytes are never used to infer facts about the original capture.
nonisolated enum SyntheticIPPacketEnvelope {
    static func address(_ value: String, ipv6: Bool) -> [UInt8]? {
        var bytes = [UInt8](repeating: 0, count: ipv6 ? 16 : 4)
        let family = ipv6 ? AF_INET6 : AF_INET
        let result = value.withCString { name in
            bytes.withUnsafeMutableBytes { buffer in
                inet_pton(family, name, buffer.baseAddress)
            }
        }
        return result == 1 ? bytes : nil
    }

    static func word(_ value: Int) -> [UInt8] {
        [UInt8(value >> 8), UInt8(value & 0xFF)]
    }

    static func doubleWord(_ value: UInt32) -> [UInt8] {
        [UInt8(value >> 24), UInt8((value >> 16) & 0xFF), UInt8((value >> 8) & 0xFF), UInt8(value & 0xFF)]
    }

    static func pseudoHeader(
        source: [UInt8], destination: [UInt8], transportLength: Int, protocolNumber: UInt8, ipv6: Bool
    )
        -> [UInt8]
    {
        if ipv6 {
            return source + destination + [0, 0] + word(transportLength) + [0, 0, 0, protocolNumber]
        }
        return source + destination + [0, protocolNumber] + word(transportLength)
    }

    static func ipHeader(
        source: [UInt8], destination: [UInt8], transportLength: Int,
        protocolNumber: UInt8, ipv6: Bool
    )
        -> [UInt8]
    {
        if ipv6 {
            return [0x60, 0, 0, 0] + word(transportLength) + [protocolNumber, 64] + source + destination
        }
        var header = [0x45, 0] + word(transportLength + 20)
            + [0, 0, 0, 0, 64, protocolNumber, 0, 0] + source + destination
        let value = checksum(header)
        header[10] = UInt8(value >> 8)
        header[11] = UInt8(value & 0xFF)
        return header
    }

    static func ethernetHeader(inbound: Bool, ipv6: Bool) -> [UInt8] {
        let firstMAC: [UInt8] = [2, 0, 0, 0, 0, 1]
        let secondMAC: [UInt8] = [2, 0, 0, 0, 0, 2]
        let etherType: [UInt8] = ipv6 ? [0x86, 0xDD] : [0x08, 0]
        return (inbound ? secondMAC + firstMAC : firstMAC + secondMAC) + etherType
    }

    static func checksum(_ bytes: [UInt8]) -> UInt16 {
        var sum: UInt64 = 0
        var index = 0
        while index < bytes.count {
            sum += UInt64(bytes[index]) << 8
            if index + 1 < bytes.count {
                sum += UInt64(bytes[index + 1])
            }
            index += 2
        }
        while sum >> 16 != 0 {
            sum = (sum & 0xFFFF) + (sum >> 16)
        }
        return ~UInt16(sum)
    }
}
